          Array.isArray(item.type.options)
        ) {
          const opts: Array<string> = [];
          for (const opt of item.type.options) {
            if (typeof opt === "string") opts.push(opt);
          }
          qType = { _tag: "SingleChoice", options: opts };
        } else if (item.type._tag === "LongText") {
          qType = { _tag: "LongText" };
        }
      }
      questions.push({ id: item.id, position: item.position, text: item.text, type: qType });
    }
  }

  const actions: Array<ActionData> = [];
  if ("actions" in data && Array.isArray(data.actions)) {
    for (const act of data.actions) {
      if (
        typeof act === "object" &&
        act !== null &&
        "id" in act &&
        typeof act.id === "string" &&
        "title" in act &&
        typeof act.title === "string"
      ) {
        actions.push({ id: act.id, title: act.title });
      }
    }
  }

  return {
    roundId: data.roundId,
    pulseName: data.pulseName,
    minimumGroupSize: data.minimumGroupSize,
    questions,
    actions,
    closeTime: data.closeTime,
    state: data.state,
    hasAnswered: data.hasAnswered,
    aiProcessing,
  };
}
import * as Schema from "effect/Schema";

export const SubmissionRoundContext = Schema.Struct({
  roundId: Schema.String,
  pulseName: Schema.String,
  minimumGroupSize: Schema.Int,
  questions: Schema.Array(
    Schema.Struct({
      id: Schema.String,
      position: Schema.Int,
      text: Schema.String,
      type: Schema.Unknown,
    }),
  ),
  actions: Schema.Array(
    Schema.Struct({
      id: Schema.String,
      title: Schema.String,
    }),
  ),
  closeTime: Schema.Int,
  state: Schema.String,
  hasAnswered: Schema.Boolean,
  aiProcessing: Schema.Boolean,
});

const decode = Schema.decodeUnknownOption(SubmissionRoundContext);

export function validateRoundContext(raw: unknown): boolean {
  const result = decode(raw);
  return result._tag === "Some";
}

import { describe, expect, it } from "vitest";
import { answerCatalog } from "../messages/answer.ts";
